
# Builds content of the npm package @stopsopa/tabs in dist/ (the only directory published, see "files" in package.json):
#
#   dist/vanilla-tabs.esm.js    - ES module, main entry:  import vanillaTabs from "@stopsopa/tabs"
#   dist/vanilla-tabs.js        - classic script:         <script src=".../dist/vanilla-tabs.js">
#   dist/vanilla-tabs.css       - styles:                 import "@stopsopa/tabs/vanilla-tabs.css"
#   dist/react/index.js         - React component:        import { Tabs, Tab } from "@stopsopa/tabs/react"
#   dist/vanilla-tabs.esm.d.ts  - types of the main entry (generated by tsc from skills/vanilla-tabs/vanilla-tabs.ts)
#   dist/react/*.d.ts           - types of the React component (generated by tsc from react/)
#
# The first two are copies of the files generated by transpile.sh (it runs first) in skills/vanilla-tabs/,
# the css is a copy of skills/vanilla-tabs/vanilla-tabs.css
#
# Usage (from any directory):
#
#   npm install
#   /bin/bash build.sh
#
# dist/ is not committed. On github actions it is built for every push (to prove it builds)
# and published to npm when a tag is pushed - see .github/workflows/deploy.yaml and NPM_RELEASE.md

_SHELL="$(ps -p $$ -o comm=)"; # bash || sh || zsh
_SHELL="$(basename ${_SHELL//-/})"
case ${_SHELL} in
  zsh)
    _DIR="$( cd "$( dirname "${(%):-%x}" )" && pwd -P )"
    ;;
  sh)
    _DIR="$( cd "$( dirname "${0}" )" && pwd -P )"
    ;;
  *)
    _DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" && pwd -P )"
    ;;
esac

set -e

cd "${_DIR}"

ESBUILD="node_modules/.bin/esbuild"

TSC="node_modules/.bin/tsc"

if [[ ! -f "${ESBUILD}" || ! -f "${TSC}" ]]; then
  echo "${0} error: ESBUILD=>${ESBUILD}< or TSC=>${TSC}< not found, run 'npm install' first"

  exit 1
fi

/bin/bash transpile.sh

rm -rf dist

mkdir -p dist/react

for FILE in vanilla-tabs.js vanilla-tabs.esm.js vanilla-tabs.css; do
  cp "skills/vanilla-tabs/${FILE}" "dist/${FILE}"
done

BANNER="/**
 * https://github.com/stopsopa/tabs
 *
 * GENERATED FILE - don't edit. Source: react/Tabs.tsx
 */"

# react is not bundled: it comes from the project using the component (peerDependencies)
"${ESBUILD}" react/index.ts \
  --bundle \
  --format=esm \
  --jsx=automatic \
  --external:react \
  --external:react/jsx-runtime \
  --outfile=dist/react/index.js \
  --target=es2020 \
  --charset=utf8 \
  --banner:js="${BANNER}"

# types. tsc mirrors the layout of the sources (dist/skills/vanilla-tabs/vanilla-tabs.d.ts, dist/react/*.d.ts),
# types of the library are moved next to the ES module they describe
"${TSC}" -p tsconfig.build.json

mv dist/skills/vanilla-tabs/vanilla-tabs.d.ts dist/vanilla-tabs.esm.d.ts

rm -rf dist/skills

cat <<EEE

${0}: dist/ is ready:

$(find dist -type f | sort)

EEE
